import {careerLanguage} from './career-language.js?v=0.31.0';
import {curiosity} from './content.js?v=0.31.0';
import {occupationEssentials} from './occupation-essentials.js?v=0.31.0';
export const matchingVersion='2.4.0';
export const interestNames={R:'Making & doing',I:'Investigating',A:'Creating',S:'Helping & teaching',E:'Leading & persuading',C:'Organizing & checking'};
export const fieldThemes={creative:['A'],technology:['I','C'],health:['S','I'],business:['E','C'],science:['I','R'],building:['R','I'],trades:['R'],services:['S','R','E'],education:['S'], 'public-safety':['R','S'],'transportation-production':['R','C'],'sales-office':['E','C']};
export const taskPrompts={
 'Accounting':'Keep financial records accurate.','Agriculture':'Grow crops and look after plants.','Animal Service':'Care for animals.','Applied Arts and Design':'Design something useful and appealing.','Athletics':'Coach, train, or support physical activity.','Business Initiatives':'Develop a business idea.','Construction/Woodwork':'Build or improve physical structures.','Creative Writing':'Write an original story or message.','Culinary Art':'Prepare and present food.','Engineering':'Design and test how something works.','Finance':'Help people make financial decisions.','Health Care Service':'Provide practical care for patients.','Human Resources':'Support people at work.','Humanities':'Explore languages, history, and culture.','Information Technology':'Build or troubleshoot digital tools.','Law':'Understand rules and advocate for people.','Life Science':'Investigate living systems.','Management/Administration':'Coordinate people and daily operations.','Marketing/Advertising':'Understand an audience and communicate an idea.','Mathematics/Statistics':'Find patterns in numbers.','Mechanics/Electronics':'Fix or maintain equipment.','Media':'Create and share media.','Medical Science':'Investigate symptoms and treatment.','Music':'Make or perform music.','Nature/Outdoors':'Work with natural places outdoors.','Office Work':'Keep records, schedules, and details organized.','Performing Arts':'Create a live performance.','Personal Service':'Help someone look or feel their best.','Physical Science':'Investigate materials and physical processes.','Physical/Manual Labor':'Do hands-on, active work.','Politics':'Help shape public decisions.','Professional Advising':'Guide someone through a decision.','Protective Service':'Keep people safe and respond to incidents.','Public Speaking':'Explain ideas to an audience.','Religious Activities':'Support a faith community.','Sales':'Help customers choose a product or service.','Social Science':'Understand people and communities through evidence.','Social Service':'Help people navigate a difficult situation.','Teaching/Education':'Help someone learn something new.','Transportation/Machine Operation':'Move goods or operate equipment carefully.','Visual Arts':'Create photographs, drawings, or visual art.'
};
Object.assign(taskPrompts,Object.fromEntries(Object.entries(careerLanguage).map(([id,tasks])=>['work:'+id,tasks[0]])));
export function interestPicture(state,questions=curiosity){
 const groups=Object.fromEntries(Object.keys(interestNames).map(theme=>{const answered=questions.filter(q=>q.theme===theme&&Number.isInteger(state.curiosity?.[q.id]));return [theme,{theme,count:answered.length,mean:answered.length?answered.reduce((n,q)=>n+state.curiosity[q.id],0)/answered.length:null,likes:answered.filter(q=>state.curiosity[q.id]>=4).map(q=>q.text)}];}));
 const required=questions.length>30?6:3,minLikes=questions.length>30?3:2;const enough=Object.values(groups).every(x=>x.count>=required),means=Object.values(groups).map(x=>x.mean).filter(x=>x!==null),flat=enough&&Math.max(...means)-Math.min(...means)<.5;
 const positive=Object.values(groups).filter(x=>x.count>=required&&x.mean>=3.5&&x.likes.length>=minLikes);
 return {version:matchingVersion,groups,enough,flat,kind:!means.length?'empty':!enough?'partial':flat?'broad':positive.length?'differentiated':'open',positive:flat||(!enough&&questions.length<=30)?[]:positive.map(x=>x.theme),unknown:questions.filter(q=>state.curiosity?.[q.id]==='untried').length};
}
const fieldActivityLinks=Object.fromEntries(Object.entries({creative:[1,3,9,15,21,27],technology:[1,7,8,12,13,18,26],health:[4,10,14,16,22,28],business:[5,6,11,12,17,18,23,24,29,30],science:[2,8,14,19,20,26],building:[1,2,7,8,13,25,26],trades:[1,7,13,24,25],services:[4,16,17,19,21,24,28,29],education:[4,10,11,16,22,28],'public-safety':[7,10,13,16,24,25,28],'transportation-production':[6,12,18,24,25,30],'sales-office':[5,6,11,12,17,18,23,24,29,30]}).map(([id,items])=>[id,items.map(n=>'curiosity-'+n)]));
export function fieldConnection(state,familyId,questions=curiosity,picture){const p=picture||interestPicture(state,questions),themes=(fieldThemes[familyId]||[]).filter(t=>p.positive.includes(t)),weights={health:{S:.65,I:.35},science:{I:.8,R:.2},building:{R:.6,I:.4}},blend=(questions.length>30?{technology:{I:.7,C:.3},business:{E:.6,C:.4},services:{S:.45,R:.35,E:.2},'public-safety':{S:.55,R:.45},'transportation-production':{R:.65,C:.35},'sales-office':{E:.6,C:.4}}[familyId]:null)||weights[familyId],complete=blend&&Object.keys(blend).every(t=>p.groups[t].count>=3),score=questions.length>30?Math.max(...(fieldThemes[familyId]||[]).map(t=>p.groups[t]?.mean||0)):blend?(complete?Object.entries(blend).reduce((n,[t,w])=>n+p.groups[t].mean*w,0):0):(fieldThemes[familyId]||[]).length?Math.max(...(fieldThemes[familyId]||[]).map(t=>p.groups[t]?.mean||0)):0,themeEvidence=themes.length>0;const linked=fieldActivityLinks[familyId]||[],answered=questions.filter(q=>(linked.includes(q.id)||q.fields?.includes(familyId))&&Number.isInteger(state.curiosity?.[q.id])),activityGroups=(fieldThemes[familyId]||[]).map(t=>answered.filter(q=>q.theme===t)).filter(qs=>qs.length>=3),activityMean=questions.length>30&&activityGroups.length?Math.max(...activityGroups.map(qs=>qs.reduce((n,q)=>n+state.curiosity[q.id],0)/qs.length)):answered.length>=3?answered.reduce((n,q)=>n+state.curiosity[q.id],0)/answered.length:null,orderedScore=activityMean===null?score:.6*activityMean+.4*score,themeLikes=answered.filter(q=>p.positive.includes(q.theme)&&state.curiosity[q.id]>=4).length,localLikes=answered.filter(q=>(fieldThemes[familyId]||[]).includes(q.theme)&&state.curiosity[q.id]>=4).length,localEvidence=questions.length>30&&p.enough&&!p.flat&&localLikes>=3,supported=(themeEvidence||localEvidence)&&(localEvidence||score>=3.5||(questions.length>30&&(activityMean>=3.5||themeLikes>=3)));return {supported,activityIds:supported?answered.filter(q=>state.curiosity[q.id]>=4).map(q=>q.id):[],score:supported?orderedScore:0,reasons:supported?answered.filter(q=>state.curiosity[q.id]>=4).map(q=>q.text).slice(0,2):[],themes:supported?themes:[]};}

export function taskAreasFor(o){return (occupationEssentials[o?.soc]?.specificInterests||[]).map(x=>x.name).filter(x=>taskPrompts[x]);}
export function taskChoicesFor(careers,paths=[]){const groups=paths.map(path=>careers.filter(o=>o.pathIds.includes(path))),ordered=[],seen=new Set();if(groups.length){for(let i=0;i<Math.max(...groups.map(g=>g.length));i++)for(const group of groups){const o=group[i];if(o&&!seen.has(o.id)){seen.add(o.id);ordered.push(o);}}}for(const o of careers)if(!seen.has(o.id)){seen.add(o.id);ordered.push(o);}return ordered.map(o=>({id:'work:'+o.id,text:taskPrompts['work:'+o.id]||taskAreasFor(o).map(t=>taskPrompts[t])[0]})).filter(x=>x.text);}

export function careerConnection(state,o){const chosen=state.guide?.taskInterests||[],areas=taskAreasFor(o),tasks=[...(chosen.includes('work:'+o.id)?['work:'+o.id]:[]),...areas.filter(a=>chosen.includes(a))],p=interestPicture(state),top=(occupationEssentials[o?.soc]?.interests||[]).slice(0,2).map(x=>Object.keys(interestNames).find(t=>({R:'Realistic',I:'Investigative',A:'Artistic',S:'Social',E:'Enterprising',C:'Conventional'})[t]===x.name)),themes=top.filter(t=>p.positive.includes(t));return {taskCount:tasks.length,themeCount:themes.length,reasons:tasks.map(t=>taskPrompts[t]),themes,label:tasks.length?'Connects with your chosen tasks':themes.length?'Connects with your broad interests':'Something to explore',basis:'Editorial exploration links using your selections and O*NET occupation descriptors. Not a validated match score or aptitude measure.'};}
